WITH kept_keys AS (SELECT carrier FROM shipments EXCEPT ALL SELECT carrier FROM shipments WHERE delivered_date < '2023-08-01'), verified AS (SELECT s.* FROM shipments s INNER JOIN kept_keys k ON s.carrier = k.carrier) SELECT s.order_id, s.carrier, s.shipped_date, s.delivered_date, s.cost, s.status, (SELECT AVG(t2.cost) FROM shipments t2 WHERE t2.order_id = s.order_id) AS avg_shipment_cost FROM verified s ORDER BY shipped_date NULLS FIRST;
